use vstd::prelude::*;

verus! {
    // Intersperse a delimiter between consecutive elements of an integer slice.
    // If the input is empty, the result is empty.
    // Otherwise, for input of length n > 0, the result has length 2*n - 1,
    // with original elements at even positions and the delimiter at odd positions.
    fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
        ensures
            // final length
            res.len() == if numbers.len() == 0 { 0 } else { 2 * numbers.len() - 1 },
            // content property: for all valid indices of the result,
            // even indices come from the original array,
            // odd indices equal the delimiter
            forall |i: usize| i < res.len() ==>
                if i % 2 == 0 {
                    res[i] == numbers[i / 2]
                } else {
                    res[i] == delim
                },
    {
        let n = numbers.len();
        let mut res: Vec<i32> = Vec::new();
        if n == 0 {
            // nothing to do: res is already empty
        } else {
            // reserve exact capacity 2*n - 1 to avoid reallocations
            res.reserve_exact(2 * n - 1);
            // start by pushing the first element
            res.push(numbers[0]);
            // i = number of elements from `numbers` processed so far
            let mut i: usize = 1;
            while i < n
                invariant
                    // i always in [1, n]
                    1 <= i && i <= n,
                    // after processing i elements, res.len() == 2*i - 1
                    res.len() == 2 * i - 1,
                    // for all j < i, res[2*j] == numbers[j]
                    forall |j: usize| j < i ==> res[2*j] == numbers[j],
                    // for all j < i - 1, res[2*j + 1] == delim
                    forall |j: usize| j + 1 < i ==> res[2*j + 1] == delim,
                decreases n - i,
            {
                // intersperse by pushing delim then the next number
                res.push(delim);
                res.push(numbers[i]);
                i += 1;
            }
        }
        res
    }
}

fn main() {
    // Example usages (not verified by Verus, just runtime tests)
    let empty: Vec<i32> = vec![];
    assert!(intersperse(&empty, 42) == vec![]);

    let xs = vec![1, 2, 3];
    assert!(intersperse(&xs, 0) == vec![1, 0, 2, 0, 3]);
}